style.css:
@-moz-document domain("pinterest.com") {
/* --- STYLISH SAILOR MOON COMPLETE OVERHAUL --- */
    
    :root {
        /* Deep Outer Senshi / Cosmos Palette */
        --sm-space-dark: #0f0c1b;       /* Deep Midnight Universe */
        --sm-cosmic-purple: #1d1637;    /* Nebula Base */
        --sm-neon-pink: #ff6097;        /* Prism Power Pink Glow */
        --sm-cyber-lavender: #dcd1f3;   /* Bright Crystal Tokyo Violet */
        --sm-tiara-gold: #ffe066;       /* Moon Tiara Gold */
        --sm-text-light: #ffffff;       /* Crisp White Text */
        --sm-text-dim: #b8afdc;         /* Soft Lavender for Muted Text */
        
        /* Magical Glowing Gradients */
        --sm-crystal-glow: linear-gradient(135deg, rgba(255, 96, 151, 0.15), rgba(220, 209, 243, 0.15));
        --sm-border-glow: linear-gradient(90deg, var(--sm-neon-pink), var(--sm-cyber-lavender));
    }

    /* ? Complete Background Realism */
    body, html, #page-container, .App, [data-test-id="full-width-wrapper"], [data-test-id="masonry-container"] {
        background-color: var(--sm-space-dark) !important;
        /* High-quality repeating aesthetic star/cloud backdrop */
        background-image: 
            linear-gradient(to bottom, rgba(15, 12, 27, 0.85), rgba(29, 22, 55, 0.95)),
            url('https://unsplash.com') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        color: var(--sm-text-light) !important;
    }

    /* ? Floating Cosmic Navigation Bar */
    [data-test-id="HeaderContent"], nav, header {
        background: rgba(29, 22, 55, 0.75) !important;
        backdrop-filter: blur(20px) saturate(180%) !important;
        border-bottom: 2px solid rgba(220, 209, 243, 0.2) !important;
        box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37) !important;
    }

    /* Text & Icon Color Adaptations for Navigation */
    div, span, a, svg {
        color: inherit;
    }
    
    /* ? Glow-in-the-Dark Search Bar */
    [data-test-id="search-box-input"], [data-test-id="search-box"] form {
        background-color: rgba(15, 12, 27, 0.6) !important;
        border: 1px solid rgba(220, 209, 243, 0.3) !important;
        color: var(--sm-text-light) !important;
        border-radius: 30px !important;
    }
    
    [data-test-id="search-box-input"]::placeholder {
        color: var(--sm-text-dim) !important;
    }

    /* ? Holographic Grid Pin Cards */
    [data-test-id="pin"], [data-test-id="pin-visual-wrapper"], .Grid__Item {
        border-radius: 20px !important;
        background: rgba(29, 22, 55, 0.4) !important;
        backdrop-filter: blur(5px) !important;
        border: 1px solid rgba(255, 96, 151, 0.15) !important;
        padding: 4px !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2) !important;
    }

    /* Levitation Hover Effect with Silver Millennium Aura */
    [data-test-id="pin"]:hover {
        transform: translateY(-8px) scale(1.03) !important;
        border-color: var(--sm-neon-pink) !important;
        box-shadow: 0 0 25px rgba(255, 96, 151, 0.4), 0 0 50px rgba(220, 209, 243, 0.1) !important;
    }

    /* ? Cosmic Compact "Save" Button */
    [data-test-id="PinActionButton"], 
    [data-test-id="save-button"],
    button[class*="SaveButton"] {
        background: linear-gradient(45deg, #ff4081, #ff80ab) !important;
        color: #ffffff !important;
        border-radius: 20px !important;
        text-shadow: 0 1px 2px rgba(0,0,0,0.2) !important;
        box-shadow: 0 4px 15px rgba(255, 64, 129, 0.4) !important;
    }

    [data-test-id="PinActionButton"]:hover, 
    [data-test-id="save-button"]:hover {
        background: linear-gradient(45deg, #ff80ab, #ffe066) !important; /* Transforms to gold shimmer */
        color: #000000 !important;
        box-shadow: 0 0 20px var(--sm-tiara-gold) !important;
    }

    /* ? Royal Moon Profile Ornaments */
    [data-test-id="user-profile-avatar"], .ReactSquareShear, img[src*="user"] {
        border-radius: 50% !important;
        border: 3px double var(--sm-tiara-gold) !important;
        box-shadow: 0 0 15px rgba(255, 224, 102, 0.5) !important;
    }

    /* Text Adjustments inside Pinterest Hubs */
    h1, h2, h3, [data-test-id="pinTitle"] {
        color: var(--sm-text-light) !important;
    }
    
    [data-test-id="pinCreatorName"], p {
        color: var(--sm-text-dim) !important;
    }

    /* ? Custom Stardust Scrollbar */
    ::-webkit-scrollbar {
        width: 12px !important;
    }
    ::-webkit-scrollbar-track {
        background: var(--sm-space-dark) !important;
    }
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(var(--sm-neon-pink), var(--sm-cyber-lavender)) !important;
        border-radius: 10px !important;
        border: 3px solid var(--sm-space-dark) !important;
    }
}
